INSERT INTO "roles" ("id", "name", "display_name", "description", "permissions", "created_at", "updated_at") VALUES 
(1, 'admin', 'System Administrator', 'Akses penuh kepada konfigurasi sistem, pentadbiran pengguna, dan audit log.', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39'),
(2, 'ketua_jabatan', 'Ketua Jabatan', 'Kuasa melulus pelarasan, pelupusan, hapus kira dan laporan kedudukan stok.', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39'),
(3, 'pegawai_stor', 'Pegawai Stor', 'Pengurusan daftar stok KEW.PS-3, pengeluaran, pembungkusan dan lokasi simpanan.', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39'),
(4, 'pegawai_penerima', 'Pegawai Penerima', 'Memeriksa barang fizikal dan mengeluarkan KEW.PS-1 (BTB) atau KEW.PS-2 (BPB).', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39'),
(5, 'pegawai_pelulus', 'Pegawai Pelulus', 'Meluluskan permohonan pesanan stok individu (KEW.PS-8) dan antara stor (KEW.PS-7).', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39'),
(6, 'pemverifikasi', 'Pemverifikasi Stor', 'Lembaga bebas menjalankan pemeriksaan fizikal tahunan dan mengira percanggahan.', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39'),
(7, 'urus_setia_pelupusan', 'Urus Setia Pelupusan', 'Menguruskan lembaga pemeriksa pelupusan stok dan dokumentasi pelupusan.', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39'),
(8, 'urus_setia_kehilangan', 'Urus Setia Kehilangan & Hapus Kira', 'Mengendalikan siasatan kehilangan stok, laporan polis dan syor surcaj.', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39'),
(9, 'pemohon', 'Pemohon / Staff', 'Membuat pesanan stok, memantau status pesanan dan mengesahkan penerimaan stok.', NULL, '2026-09-23 03:02:39', '2026-09-23 03:02:39')
